let cachedData: Float32Array | undefined;

export function getOpenPbrEnergyLutData(): Float32Array {
  if (cachedData) return cachedData;
  const encoded = atob(OPENPBR_ENERGY_LUT_UINT16_BASE64);
  const data = new Float32Array(encoded.length / 2);
  for (let index = 0; index < data.length; index++) {
    const byteIndex = index * 2;
    data[index] = (
      encoded.charCodeAt(byteIndex)
      | (encoded.charCodeAt(byteIndex + 1) << 8)
    ) / 65535;
  }
  cachedData = data;
  return data;
}
